# The catalog entries the agent plugins show, for POSIX sh. Source it, then
# call: tuva_print_error <code>   (prints to stderr, like the CLI)

tuva_print_error() {
	case "$(uname -s 2>/dev/null)" in
	Darwin) _tuva_os=macos ;;
	*) _tuva_os=linux ;;
	esac
	case "$1" in
	install.backend_not_staged)
		printf '%s\n' 'error: Tuva isn’t set up on this machine yet [install.backend_not_staged]' '  This command needs Tuva’s background service, which is set up the first time Tuva starts.' '  1. Run `tuva start`.' '  2. Then run this command again.' >&2
		;;
	*)
		printf 'error: [%s]\n' "$1" >&2
		;;
	esac
}
